  function handleCategoryFilters(path) {
    var $categoriesFiltersContainer = $('#categoriesFiltersContainer');
    var $categoriesFiltersCard = $('#categoriesFiltersCard');
    var loadingHtml = "<div class=\"js-loading-card d-flex align-items-center justify-content-center w-100 my-40\">\n                    <img src=\"/assets/design_1/img/loading.svg\" width=\"56\" height=\"56\">\n                </div>";
    $categoriesFiltersContainer.removeClass('d-none');
    $categoriesFiltersCard.html(loadingHtml);
    $.get(path, function (result) {
      if (result.code === 200) {
        $categoriesFiltersCard.html(result.html);
      }
    }).fail(function () {
      $categoriesFiltersContainer.addClass('d-none');
      $categoriesFiltersCard.html('');
      showToast('error', oopsLang, somethingWentWrongLang);
    });
  }
  $('body').on('change', '#jobCategories', function (e) {
    e.preventDefault();
    var category_id = this.value;
    var path = "/panel/jobs/filters/get-by-category-id/".concat(category_id);
    handleCategoryFilters(path);
  });

  // =========
  // Payment Type
  // ======

  $('body').on('change', '.js-job-payment-type-select', function (e) {
    e.preventDefault();
    var value = $(this).val();
    var $fixed = $('.js-fixed-salary-field');
    var $range = $('.js-range-salary-field');
    $fixed.addClass('d-none');
    $range.addClass('d-none');
    if (value === 'fixed_amount') {
      $fixed.removeClass('d-none');
    } else if (value === 'range') {
      $range.removeClass('d-none');
    }
  });

